head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil40211";
scwin.displayDiv = 'validDiv';
scwin.noneDiv = 'invalidDiv';

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil40211.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "td_14", attr: "__html", fn: function () { return ([String((dma_pageContext.get("usrId") ?? ""))].some(function (v) { return String(v === null ? '' : v).trim() !== ''; }) ? ("아이디 " + String((dma_pageContext.get("usrId") ?? "")) + "는 사용하실 수 있습니다.<br/>사용하시려면 '사용하기' 버튼을 클릭하세요.") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        const v = a.fn();
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "아이디 " + String((dma_pageContext.get("usrId") ?? "")) + "는 사용하실 수 없습니다."; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.initValue();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40211.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Confirm_onclick
 * @description 「사용하기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Confirm_onclick = function(e){
    try {
        scwin.confirm()
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil40211.btn_Confirm_onclick" });
    }
};

/**
 * @method
 * @name __ev_2_btn_Confirm_onclick
 * @description __ev_2_btn_Confirm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.__ev_2_btn_Confirm_onclick = function(e){
    try {
        scwin.confirm()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40211.__ev_2_btn_Confirm_onclick' }); }
};

/**
 * @method
 * @name btn_ChkDuplicate_onclick
 * @description 「중복확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ChkDuplicate_onclick = async function(e){
    try {
        await scwin.chkDuplicate()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40211.btn_ChkDuplicate_onclick' }); }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40211.btn_Close_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_ChkDuplicate
 * @description Chk Duplicate 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ChkDuplicate = async function () {
    const sbmOptions = {
        id: "tx_fn_ChkDuplicate",
        method: "post",
        action: "/outer/popRegister.do?method=searchIdDuplication",
        ref: "dma_ChkDuplicateReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initValue
 * @description init Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.initValue = function () {
    ($c.util.getComponent(scwin.displayDiv) && $c.util.getComponent(scwin.displayDiv).show ? $c.util.getComponent(scwin.displayDiv).show() : console.warn('[sdd] show 대상 미해결: ' + scwin.displayDiv));
    ($c.util.getComponent(scwin.noneDiv) && $c.util.getComponent(scwin.noneDiv).hide ? $c.util.getComponent(scwin.noneDiv).hide() : console.warn('[sdd] hide 대상 미해결: ' + scwin.noneDiv));
};

/**
 * @method
 * @name confirm
 * @description confirm 처리
 * @returns {void}
 * @hidden N
 */
scwin.confirm = function () {
    (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).fn_UseUsrId === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).fn_UseUsrId($c.util.getComponent('ipt_usrId').getValue()) : void 0), $c.win.closePopup([$c.util.getComponent('ipt_usrId').getValue()]));
    scwin.close();
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name chkDuplicate
 * @description chk Duplicate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkDuplicate = async function () {
    // TODO Stage2: $c.cm.fn_* 정의 없음(pcc/fil 미반입 · 치환 방향 미결) — fn_ChkAlphaNum, fn_ChkNoneNum
    const frm = $c.util.getComponent('idForm');
    const usrIdObj = $c.util.getComponent('ipt_usrId');
    if (await scwin.checkRequired(usrIdObj)) {
        return;
    }
    if (!$c.cm.fn_ChkNoneNum(usrIdObj)) {
        return;
    }
    if (!$c.cm.fn_ChkAlphaNum(usrIdObj, 6, 20)) {
        return;
    }
    $c.util.getComponent("ipt_usrId").setValue((usrIdObj.getValue()).toLowerCase());
    frm.action = '/outer/popRegister.do?method=searchIdDuplication';
    await scwin.tx_fn_ChkDuplicate();
};

/**
 * @method
 * @name checkRequired
 * @description 필수 입력 검사 — 값이 비면 항목명으로 알리고 포커스를 준 뒤 true(as-is fn_NullChk 의미 보존 · pcc/fil 반입 후보)
 * @param {Object} comp 입력 컴포넌트
 * @returns {Promise<Boolean>} 비어 있으면 true
 * @hidden N
 */
scwin.checkRequired = async function (comp) {
    if (!comp || !$c.util.isEmpty($c.str.trim(String(comp.getValue() ?? "")))) { return false; }
    const name = (typeof comp.getTitle === "function" && comp.getTitle()) || comp.getID();
    await $c.win.alert("'" + name + "' 항목을 입력하세요");
    comp.focus();
    return true;
};
